def j(n): return json.load(open(os.path.join(R, n)))


def runs(arch):
    out = {}
    for f in ('none', 'forward', 'cp_plus1', 'cp_minus1', 'tr_zero', 'skip_storage', 'skip_transient', 'skip_warm',
              'sstore_nojournal', 'sstore_prev_new'):
        d = j('journal_%s_%s_real.json' % (arch, f)); out[f] = d
    out['const'] = j('journal_%s_none_const.json' % arch)
    return out


A, X = runs('a64'), runs('x64')
live, live14 = j('live_swap_revert.json'), j('live_swap_revert_t14.json')


def faults_text(r):
    names = {'forward': 'entries undone oldest first', 'cp_plus1': 'checkpoint index plus one', 'cp_minus1': 'checkpoint index minus one',
             'tr_zero': 'transient entry restored to zero', 'skip_storage': 'StorageChange arm skipped',
             'skip_transient': 'TransientStorageChange arm skipped', 'sstore_nojournal': 'SSTORE writes without a StorageChange entry',
             'sstore_prev_new': 'SSTORE journals the new value as the previous one'}
    return '; '.join('%s %d of %d' % (names[k], r[k]['mismatch'], r[k]['cases']) for k in names)


cov_a, cov_x = A['none']['coverage'], X['none']['coverage']
def cov(c): return ', '.join('%s %d of %d' % (k, v[0], v[1]) for k, v in c.items())

